def main():
    repo, svg = sys.argv[1], sys.argv[2]
    by = {}
    for c, t, after, h, say in WHY: by.setdefault(c, []).append((t, after, h, say))
    for c, items in by.items():
        p = os.path.join(repo, 'courses', c, 'course.json'); d = json.load(open(p, encoding='utf-8'))
        sl = [s for s in d['lecture']['slides'] if not s.get('why')]
        for t, after, h, say in items:
            shutil.copy(os.path.join(svg, f'why_{t}.svg'), os.path.join(repo, 'courses', c, 'img', f'why_{t}.svg'))
            i = next(k for k, s in enumerate(sl) if s.get('h') == after)
            sl.insert(i + 1, {'layout': 'image', 'h': h, 'img': f'img/why_{t}.svg', 'why': t, 'say': say})
        d['lecture']['slides'] = sl
        open(p, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=2) + '\n')
        print(c, len(sl), 'слайдов;', ', '.join(f'{t}→{[s.get("why") for s in sl].index(t) + 1}' for t, *_ in items), '; слов:', ', '.join(str(len(x[3].split())) for x in items))


if __name__ == '__main__':
    main()
